(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.LineLesson,number=window.LinearLesson;
function tex(n){return number.fractionTex(number.rational(Math.round(n*2),2));}
function math(host,source){const e=document.createElement('span');e.dataset.tex=source;host.replaceChildren(e);}
function equation(m,b){return 'y='+ (m===0?String(b):(m===1?'x':m===-1?'-x':tex(m)+'x')+(b===0?'':b>0?'+'+b:String(b)));}
for(let n=-5;n<=5;n++){if(n===0)continue;for(const axis of ['x','y']){const e=document.createElement('span');e.className='tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=(axis==='x'?50+n*100/12:46)+'%';e.style.top=(axis==='y'?50-n*100/12:54)+'%';$('#ticks').append(e);}}
function draw(){const m=Number($('#slope').value),b=Number($('#intercept').value),ends=core.clip(m,b),first=core.point(ends[0].x,ends[0].y),last=core.point(ends[1].x,ends[1].y),a=core.point(0,b),c=core.point(1,b),d=core.point(1,b+m);$('#slope-output').value=m;$('#intercept-output').value=b;for(const [key,value] of Object.entries({x1:first.x,y1:first.y,x2:last.x,y2:last.y}))$('#graph-line').setAttribute(key,value);$('#slope-triangle').setAttribute('d',`M ${a.x} ${a.y} L ${c.x} ${c.y} L ${d.x} ${d.y}`);for(const [id,pos] of [['intercept-dot',a],['step-dot',d]]){document.getElementById(id).setAttribute('cx',pos.x);document.getElementById(id).setAttribute('cy',pos.y);}math($('#line-equation'),equation(m,b));math($('#change-equation'),`m=\\frac{${tex(m)}}{1}=${tex(m)}`);const description=(m===0?'Garis mendatar.':m>0?'Garis naik dari kiri ke kanan.':'Garis turun dari kiri ke kanan.')+` Titik potong tegaknya (0, ${b}). Untuk satu satuan ke kanan, perubahan tegaknya ${m}.`;$('#line-feedback').innerHTML=(m===0?'Garis mendatar.':m>0?'Garis naik dari kiri ke kanan.':'Garis turun dari kiri ke kanan.')+` Titik potong tegaknya <span data-tex="(0,${b})"></span>. Untuk satu satuan ke kanan, perubahan tegaknya <span data-tex="${tex(m)}"></span>.`;$('#line-plane').setAttribute('aria-label',`Grafik y sama dengan ${m} kali x ditambah ${b}. `+description);}
$('#slope').addEventListener('input',draw);$('#intercept').addEventListener('input',draw);$('#reset-line').addEventListener('click',()=>{$('#slope').value=1;$('#intercept').value=1;draw();});draw();
const questions=[
{prompt:'Tentukan gradien garis melalui dua titik ini.',tex:'(1,2)\\quad\\text{dan}\\quad(3,3)',n:1,d:2,hint:'Perubahan tegak adalah satu; perubahan mendatar adalah dua.',why:'Gradiennya setengah, yaitu perubahan tegak satu dibagi perubahan mendatar dua.'},
{prompt:'Tentukan gradien garis melalui dua titik ini.',tex:'(0,3)\\quad\\text{dan}\\quad(2,-1)',n:-2,d:1,hint:'Kurangi koordinat kedua titik dengan urutan yang sama: negatif satu dikurangi tiga, lalu dua dikurangi nol.',why:'Perubahan tegak negatif empat dibagi perubahan mendatar dua menghasilkan negatif dua.'},
{prompt:'Berapa nilai titik potong tegak pada persamaan ini?',tex:'y=-3x+4',n:4,d:1,hint:'Substitusikan nol untuk koordinat mendatar.',why:'Saat koordinat mendatar nol, koordinat tegak bernilai empat. Titik potongnya memiliki koordinat mendatar nol dan koordinat tegak empat.'},
{prompt:'Garis bergradien dua melalui titik berikut. Berapa nilai titik potong tegaknya?',tex:'(1,5)',n:3,d:1,hint:'Masukkan koordinat titik dan gradien ke bentuk persamaan pada lab, lalu cari konstanta yang belum diketahui.',why:'Lima sama dengan dua kali satu ditambah konstanta. Jadi nilai titik potong tegaknya tiga.'},
{prompt:'Berapa gradien garis mendatar berikut?',tex:'y=-2',n:0,d:1,hint:'Nilai tegak tidak berubah ketika nilai mendatar berubah.',why:'Perubahan tegak nol, sehingga gradiennya nol. Ini berbeda dari garis tegak.'}
];const solved=new Set();function report(i,ok,message){const e=$('#feedback'+i);e.textContent=message;e.className='feedback '+(ok?'correct':'incorrect');if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p>${q.prompt}</p><p data-tex="${q.tex}"></p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" autocomplete="off" required aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=number.parseAnswer($('#answer'+i).value),ok=number.equalAnswer(a,number.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya -2 atau 1/2.':'Belum tepat. Periksa urutan pengurangan atau buka petunjuk.');}));$('#check-vertical').addEventListener('click',()=>{const a=$('[name="vertical-answer"]:checked'),ok=a?.value==='undefined';report(5,ok,!a?'Pilih jawaban dahulu.':ok?'Tepat. Perubahan mendatar nol, sehingga gradien tidak terdefinisi.':'Belum tepat. Perubahan mendatarnya nol. Membagi dengan nol tidak terdefinisi; ini berbeda dari hasil nol.');});
const storage={get(k){try{return localStorage.getItem('fondasi-line-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-line-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function completed(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>completed(storage.set('complete','yes')));if(storage.get('complete')==='yes')completed(true);
})();